mapper.select:
select ifnull(MAX( CAST(
ifnull(substring(BUS_VOUCHNUM,-8),'00000000')
AS SIGNED INTEGER)),'000000') from BOK_VOUCH_MAIN where VOUCH_YEAR = #{vouchYear} AND VOUCH_MONTH = #{vouchMonth} AND BOOKSET_ID = #{booksetId}

mapper.update:
update BOK_VOUCH_MAIN
set BUS_VOUCHNUM = concat_ws('', substring(BUS_VOUCHNUM,1, length(BUS_VOUCHNUM)-6) , '00' , substring(BUS_VOUCHNUM,-6))
where VOUCH_YEAR = #{vouchYear} AND VOUCH_MONTH = #{vouchMonth}
